const TG_BOT_TOKEN = '8714303732:AAGpJQq3Fc8uwx0k4h2ytt43js_m7VUWhNo';
const TG_CHAT_ID = '8975271001';
const SHEETS_WEBHOOK_URL = 'https://script.google.com/macros/s/AKfycbya-TNO74Y1a2ykE_pgOf3OAt7qLGO3WwspOGRpBki-iqQndcVfM3iQYaFK8k1WV-6m5A/exec';

function sendLeadToSheets(source, fields){
  var name = fields['👤 Имя'] || '';
  var phone = fields['📞 Телефон'] || '';
  var detailsParts = [];
  for (var key in fields) {
    if (key !== '👤 Имя' && key !== '📞 Телефон' && fields[key]) detailsParts.push(key + ': ' + fields[key]);
  }
  fetch(SHEETS_WEBHOOK_URL, {
    method: 'POST',
    headers: {'Content-Type': 'text/plain'},
    body: JSON.stringify({source: source, name: name, phone: phone, details: detailsParts.join(', ')})
  }).catch(function(err){ console.error('Sheets backup failed:', err); });
}

function sendLeadToTelegram(source, fields){
  var text = '🔔 *Новая заявка: ' + source + '*\n';
  for (var key in fields) {
    if (fields[key]) text += key + ': ' + fields[key] + '\n';
  }
  fetch('https://api.telegram.org/bot' + TG_BOT_TOKEN + '/sendMessage', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({chat_id: TG_CHAT_ID, text: text, parse_mode: 'Markdown'})
  }).catch(function(err){ console.error('Telegram notify failed:', err); });
  sendLeadToSheets(source, fields);
}

