// ===== TIMER =====
function updateTimer(){
  if(!document.getElementById('t-days'))return;
  const end=new Date(2026,8,30,23,59,59);
  const d=end-new Date(); if(d<=0)return;
  const pad=n=>String(Math.floor(n)).padStart(2,'0');
  document.getElementById('t-days').textContent=pad(d/86400000);
  document.getElementById('t-hours').textContent=pad((d%86400000)/3600000);
  document.getElementById('t-mins').textContent=pad((d%3600000)/60000);
  document.getElementById('t-secs').textContent=pad((d%60000)/1000);
}
updateTimer();

// ===== QUIZ =====
const quizData={housing:null,type:null,area:50,style:[],timing:null};
const quizPrices={'Смарт ремонт':25000,'Стандартный ремонт':20000,'Дизайнерский ремонт':33800,'Приёмка квартиры':350};

function selectOpt(el,key,val){
  el.closest('.quiz-options').querySelectorAll('.quiz-option').forEach(o=>o.classList.remove('selected'));
  el.classList.add('selected'); quizData[key]=val;
  const n=parseInt(el.closest('.quiz-step').id.replace('qs-',''));
  const btn=document.getElementById('qnext-'+n); if(btn)btn.disabled=false;
}
function toggleOpt(el,key,val){
  el.classList.toggle('selected');
  quizData[key]=el.classList.contains('selected')
    ?[...quizData[key],val]
    :quizData[key].filter(v=>v!==val);
  const n=parseInt(el.closest('.quiz-step').id.replace('qs-',''));
  const btn=document.getElementById('qnext-'+n); if(btn)btn.disabled=quizData[key].length===0;
}
function nextStep(cur){
  document.getElementById('qs-'+cur).classList.remove('active');
  document.getElementById('qs-'+(cur+1)).classList.add('active');
  document.getElementById('quiz-progress').style.width=((cur+1)/5*100)+'%';
  document.getElementById('calculator').scrollIntoView({behavior:'smooth',block:'start'});
}
function prevStep(cur){
  document.getElementById('qs-'+cur).classList.remove('active');
  document.getElementById('qs-'+(cur-1)).classList.add('active');
  document.getElementById('quiz-progress').style.width=((cur-1)/5*100)+'%';
  document.getElementById('calculator').scrollIntoView({behavior:'smooth',block:'start'});
}
function showQuizResult(){
  const tags=[quizData.housing,quizData.type,quizData.timing,...(quizData.style||[])].filter(Boolean);
  document.getElementById('qr-tags').innerHTML=tags.map(t=>`<span class="quiz-result-tag">${t}</span>`).join('');
  const type = quizData.type || 'Смарт ремонт';
  const area = quizData.area || 50;
  const pricePerM = quizPrices[type] !== undefined ? quizPrices[type] : quizPrices['Смарт ремонт'];
  const isFlat = type === 'Приёмка квартиры';
  const total = isFlat ? pricePerM : pricePerM * area;
  const fmt = n => n.toLocaleString('ru-RU');
  const priceNumEl = document.getElementById('qr-price-num');
  if(priceNumEl){
    priceNumEl.textContent = 'от '+fmt(total)+' ₽';
    document.getElementById('qr-price-type').textContent = type;
    document.getElementById('qr-price-area-row').style.display = isFlat ? 'none' : 'flex';
    document.getElementById('qr-price-area').textContent = area+' м²';
    document.getElementById('qr-price-permeter-label').textContent = isFlat ? 'Стоимость приёмки' : 'Цена за м²';
    document.getElementById('qr-price-permeter').textContent = isFlat ? fmt(pricePerM)+' ₽' : fmt(pricePerM)+' ₽/м²';
  }
  document.getElementById('qs-5').classList.remove('active');
  document.getElementById('qs-result').classList.add('active');
  document.getElementById('quiz-progress').style.width='100%';
  document.getElementById('calculator').scrollIntoView({behavior:'smooth',block:'start'});
}
function submitQuizContact(e){
  e.preventDefault();
  var name=document.getElementById('qr-name').value.trim();
  var phone=document.getElementById('qr-phone').value.trim();
  if(!name||!phone){alert('Пожалуйста, укажите имя и телефон');return;}
  var consent=document.getElementById('quiz-consent');
  if(consent&&!consent.checked){alert('Пожалуйста, дайте согласие на обработку данных');return;}
  var area=quizData.area;
  var profile=[quizData.housing,quizData.type,quizData.timing].concat(quizData.style||[]).filter(Boolean).join(', ');
  data.leads.unshift({name:name,phone:phone,type:(quizData.type||'?')+', '+area+' м²',done:false,date:new Date().toLocaleDateString('ru-RU')});
  sendLeadToTelegram('Квиз-калькулятор', {'👤 Имя':name,'📞 Телефон':phone,'📐 Площадь':area+' м²','🔧 Профиль':profile});
  document.querySelector('#qs-result .quiz-result').innerHTML=
    '<div class="quiz-result-icon">✓</div>'+
    '<div class="quiz-result-title">Спасибо, '+name+'!</div>'+
    '<div class="quiz-result-sub">С вами свяжется специалист в ближайшее время</div>'+
    '<div><button class="quiz-restart" onclick="restartQuiz()">Пройти заново</button></div>';
}
function restartQuiz(){
  quizData.housing=null;quizData.type=null;quizData.area=50;quizData.style=[];quizData.timing=null;
  document.querySelectorAll('.quiz-step').forEach(s=>s.classList.remove('active'));
  document.querySelectorAll('.quiz-option').forEach(o=>o.classList.remove('selected'));
  document.querySelectorAll('.quiz-next[id]').forEach(b=>b.disabled=true);
  // Шаг 3 (площадь) всегда доступен — ползунок всегда имеет значение
  const q3btn = document.getElementById('qnext-3');
  if(q3btn) q3btn.disabled = false;
  document.getElementById('q-area-range').value=50;
  document.getElementById('q-area-num').textContent=50;
  document.getElementById('qs-1').classList.add('active');
  document.getElementById('quiz-progress').style.width='20%';
  document.getElementById('calculator').scrollIntoView({behavior:'smooth',block:'start'});
}

