function toggleFaq(el){
  // Закрываем остальные
  document.querySelectorAll('.faq-item.open').forEach(item=>{
    if(item !== el.parentElement) item.classList.remove('open');
  });
  el.parentElement.classList.toggle('open');
}

// ===== LEAD FORM =====
function submitLead(){
  const name=document.getElementById('form-name').value.trim();
  const phone=document.getElementById('form-phone').value.trim();
  const type=document.getElementById('form-type').value;
  if(!name||!phone){showToast('Заполните имя и телефон');return;}
  const consent=document.getElementById('form-consent');
  if(consent&&!consent.checked){showToast('Пожалуйста, дайте согласие на обработку данных');return;}
  const now=new Date();
  data.leads.unshift({name,phone,type,done:false,
    date:now.toLocaleDateString('ru-RU')+' '+now.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})});
  sendLeadToTelegram('Форма заявки на сайте', {'👤 Имя':name,'📞 Телефон':phone,'🔧 Услуга':type});
  document.getElementById('form-name').value='';
  document.getElementById('form-phone').value='';
  // Показываем поп-ап подтверждения
  showLeadSuccess();
}

