// Секретный вход в админку — долгое нажатие на логотип (800мс)
(function(){
  var logo = document.getElementById('site-logo');
  if(!logo) return;
  var timer;
  logo.addEventListener('mousedown', function(){ timer = setTimeout(openAdmin, 800); });
  logo.addEventListener('touchstart', function(){ timer = setTimeout(openAdmin, 800); }, {passive:true});
  logo.addEventListener('mouseup',   function(){ clearTimeout(timer); });
  logo.addEventListener('mouseleave',function(){ clearTimeout(timer); });
  logo.addEventListener('touchend',  function(){ clearTimeout(timer); });
})();
function closeAdmin(){ var m=document.getElementById('admin-modal'); if(m) m.classList.remove('open'); }
(function(){ var am=document.getElementById('admin-modal'); if(am) am.addEventListener('click',function(e){ if(e.target===this)closeAdmin(); }); })();

function showTab(tab,btn){
  document.querySelectorAll('.admin-section').forEach(s=>s.classList.remove('active'));
  document.querySelectorAll('.admin-tab').forEach(b=>b.classList.remove('active'));
  document.getElementById('tab-'+tab).classList.add('active');
  btn.classList.add('active');
  if(tab==='portfolio')renderAdminPortfolio();
  if(tab==='reviews')renderAdminReviews();
  if(tab==='leads')renderAdminLeads();
  if(tab==='seo')renderSeoChecklist();
}
