function saveSeoMeta() {
  const title = document.getElementById('seo-title').value;
  const desc = document.getElementById('seo-desc').value;
  document.getElementById('seo-preview-title').textContent = title.slice(0,60);
  document.getElementById('seo-preview-desc').textContent = desc.slice(0,160);
  // Update actual page meta
  document.title = title;
  let m = document.querySelector('meta[name="description"]');
  if (!m) { m = document.createElement('meta'); m.name='description'; document.head.appendChild(m); }
  m.content = desc;
  let k = document.querySelector('meta[name="keywords"]');
  if (!k) { k = document.createElement('meta'); k.name='keywords'; document.head.appendChild(k); }
  k.content = document.getElementById('seo-keys').value;
  showSaveNotice('seo-meta-notice'); showToast('SEO мета-теги обновлены');
}

function saveAnalytics() {
  const yaId = document.getElementById('ya-id').value.trim();
  const gaId = document.getElementById('ga-id').value.trim();
  if (yaId) {
    const s = document.createElement('script');
    s.textContent = '(function(m,e,t,r,i,k,a){m[i]=m[i]||function(){(m[i].a=m[i].a||[]).push(arguments)};m[i].l=1*new Date();k=e.createElement(t),a=e.getElementsByTagName(t)[0],k.async=1,k.src=r,a.parentNode.insertBefore(k,a)})(window,document,"script","https://mc.yandex.ru/metrika/tag.js","ym");ym('+yaId+',\'init\',{clickmap:true,trackLinks:true,accurateTrackBounce:true,webvisor:true});';
    document.head.appendChild(s);
  }
  if (gaId) {
    const s = document.createElement('script');
    s.src = 'https://www.googletagmanager.com/gtag/js?id='+gaId;
    s.async = true; document.head.appendChild(s);
    const s2 = document.createElement('script');
    s2.textContent = 'window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag(\'js\',new Date());gtag(\'config\',\''+gaId+'\');';
    document.head.appendChild(s2);
  }
  showSaveNotice('analytics-notice'); showToast('Аналитика подключена!');
}

function saveOG() {
  const ogTitle = document.getElementById('og-title').value;
  const ogDesc = document.getElementById('og-desc').value;
  const setMeta = (prop, val, attr='property') => {
    let m = document.querySelector('meta['+attr+'="'+prop+'"]');
    if (!m) { m = document.createElement('meta'); m.setAttribute(attr,prop); document.head.appendChild(m); }
    m.content = val;
  };
  setMeta('og:title', ogTitle); setMeta('og:description', ogDesc);
  setMeta('og:url', 'https://remstyle39.ru');
  setMeta('og:type', 'website');
  showSaveNotice('og-notice'); showToast('Open Graph обновлён');
}

