// ===== CALLBACK WIDGET =====
let cbCountdownInterval = null;

function openCallback(){
  document.getElementById('callback-overlay').classList.add('open');
  document.getElementById('cb-step-form').style.display = 'block';
  document.getElementById('cb-step-timer').style.display = 'none';
  document.getElementById('cb-step-success').style.display = 'none';
}
function closeCallback(){
  document.getElementById('callback-overlay').classList.remove('open');
  if(cbCountdownInterval){ clearInterval(cbCountdownInterval); cbCountdownInterval = null; }
}
document.addEventListener('DOMContentLoaded', function(){
  const ov = document.getElementById('callback-overlay');
  if(ov) ov.addEventListener('click', function(e){ if(e.target===this) closeCallback(); });
});

function formatPhone(val){
  val = val.replace(/\D/g,'');
  if(val.startsWith('8')) val = '7' + val.slice(1);
  if(!val.startsWith('7')) val = '7' + val;
  val = val.slice(0,11);
  let r = '+7';
  if(val.length > 1) r += ' (' + val.slice(1,4);
  if(val.length >= 4) r += ') ' + val.slice(4,7);
  if(val.length >= 7) r += '-' + val.slice(7,9);
  if(val.length >= 9) r += '-' + val.slice(9,11);
  return r;
}
const cbInput = document.getElementById('cb-phone-input');
if(cbInput){
  cbInput.addEventListener('input', function(){
    const pos = this.selectionStart;
    this.value = formatPhone(this.value);
  });
}

function submitCallback(){
  const phone = document.getElementById('cb-phone-input').value.trim();
  if(!phone || phone.replace(/\D/g,'').length < 10){
    document.getElementById('cb-phone-input').style.borderColor = '#f87171';
    document.getElementById('cb-phone-input').focus();
    setTimeout(()=>document.getElementById('cb-phone-input').style.borderColor='', 1500);
    return;
  }
  // Сохраняем заявку
  data.leads.unshift({
    name: 'Обратный звонок', phone: phone,
    type: 'Заказ звонка (28 сек)', done: false,
    date: new Date().toLocaleDateString('ru-RU') + ' ' + new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})
  });
  sendLeadToTelegram('Заказ обратного звонка', {'📞 Телефон':phone});
  // Переходим к экрану таймера
  document.getElementById('cb-step-form').style.display = 'none';
  document.getElementById('cb-step-timer').style.display = 'block';
  // Запускаем отсчёт
  let secs = 28;
  const countEl = document.getElementById('cb-countdown');
  const progEl = document.getElementById('cb-progress');
  countEl.textContent = secs;
  progEl.style.width = '100%';
  cbCountdownInterval = setInterval(()=>{
    secs--;
    countEl.textContent = secs;
    progEl.style.width = (secs/28*100) + '%';
    if(secs <= 0){
      clearInterval(cbCountdownInterval);
      cbCountdownInterval = null;
      document.getElementById('cb-step-timer').style.display = 'none';
      document.getElementById('cb-step-success').style.display = 'block';
    }
  }, 1000);
}

