// ===== ZHK =====




function renderZhk(filter){
  filter = filter || 'all';
  var grid = document.getElementById('zhk-grid');
  if(!grid) return;
  var filtered;
  if(filter === 'done') filtered = zhkData.filter(function(z){ return z.done > 0; });
  else if(filter === 'active') filtered = zhkData.filter(function(z){ return z.status === 'active'; });
  else if(filter === 'center') filtered = zhkData.filter(function(z){ return z.area === 'center'; });
  else if(filter === 'north') filtered = zhkData.filter(function(z){ return z.area === 'north'; });
  else if(filter === 'south') filtered = zhkData.filter(function(z){ return z.area === 'south'; });
  else if(filter === 'zelenogradsk') filtered = zhkData.filter(function(z){ return z.area === 'oblast' && z.addr && z.addr.indexOf('Зеленоградск') >= 0; });
  else if(filter === 'svetlogorsk') filtered = zhkData.filter(function(z){ return z.area === 'oblast' && z.addr && z.addr.indexOf('Светлогорск') >= 0; });
  else filtered = zhkData;

  var dotColors = { done: 'dot-done', active: 'dot-active' };
  var stColors  = { done: 's-done', active: 's-active' };

  var html = '';
  for(var i = 0; i < filtered.length; i++){
    var z = filtered[i];
    var dot = dotColors[z.status] || 'dot-new';
    var sc  = stColors[z.status]  || 's-new';
    var countHtml = '';
    if(z.done > 0){
      var word = z.done === 1 ? 'ремонт' : z.done < 5 ? 'ремонта' : 'ремонтов';
      countHtml = '<span class="zhk-card-count">' + z.done + ' ' + word + '</span>';
    }
    html += '<div class="zhk-card" onclick="openZhkModal(' + z.id + ')">'
          +   '<div class="zhk-card-top">'
          +     '<div class="zhk-card-name">' + z.name + '</div>'
          +     '<div class="zhk-card-dot ' + dot + '"></div>'
          +   '</div>'
          +   '<div class="zhk-card-bottom">'
          +     '<span class="zhk-card-status ' + sc + '">' + z.year + '</span>'
          +     countHtml
          +   '</div>'
          + '</div>';
  }
  grid.innerHTML = html;
}

function filterZhk(f,btn){
  document.querySelectorAll('.zhk-filter-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active'); renderZhk(f);
}
function openZhkModal(id){
  var z = null;
  for(var i=0;i<zhkData.length;i++){ if(zhkData[i].id===id){ z=zhkData[i]; break; } }
  if(!z) return;
  document.getElementById('zhk-modal-title').textContent = z.name;
  var chips = [
    {l:'Застройщик', v:z.developer},
    {l:'Этажность',  v:z.floors},
    {l:'Класс',      v:z.class},
    {l:'Год',        v:z.year}
  ];
  var chipsHtml = '';
  for(var i=0;i<chips.length;i++){
    chipsHtml += '<div class="zhk-modal-chip"><span>' + chips[i].l + '</span>' + chips[i].v + '</div>';
  }
  document.getElementById('zhk-modal-chips').innerHTML = chipsHtml;
  document.getElementById('zhk-modal-overlay').classList.add('open');
}

function closeZhkModal(){
  document.getElementById('zhk-modal-overlay').classList.remove('open');
}
function closeZhkModalOverlay(e){
  if(e.target === document.getElementById('zhk-modal-overlay')) closeZhkModal();
}


// ===== HERO SLIDER =====
let currentSlide = 0;
let heroSlides = [], heroDots = [];

function goSlide(n) {
  if (!heroSlides.length) return;
  heroSlides[currentSlide].classList.remove('active');
  heroDots[currentSlide] && heroDots[currentSlide].classList.remove('active');
  currentSlide = (n + heroSlides.length) % heroSlides.length;
  heroSlides[currentSlide].classList.add('active');
  heroDots[currentSlide] && heroDots[currentSlide].classList.add('active');
}

document.addEventListener('DOMContentLoaded', function() {
  heroSlides = Array.from(document.querySelectorAll('.hero-slide'));
  heroDots   = Array.from(document.querySelectorAll('.hero-dot'));
  if (heroSlides.length > 1) setInterval(() => goSlide(currentSlide + 1), 4000);
});

// ===== PARALLAX =====
(function(){
  // На мобиле background-attachment:fixed не работает — заменяем на JS
  const isMobile = /Mobi|Android/i.test(navigator.userAgent);
  if(!isMobile) return; // На десктопе CSS сам справляется

  const sections = document.querySelectorAll('.parallax-section');
  function updateParallax(){
    sections.forEach(sec => {
      const rect = sec.getBoundingClientRect();
      const progress = -rect.top / window.innerHeight;
      sec.style.setProperty('--parallax-y', (progress * 40) + 'px');
    });
  }
  window.addEventListener('scroll', updateParallax, {passive:true});
})();

// ===== SCROLL TOP BTN =====
window.addEventListener('scroll', function(){
  const btn = document.getElementById('scroll-top-btn');
  if(btn) btn.classList.toggle('visible', window.scrollY > 400);
});

